package org.apache.accumulo.core.fate.zookeeper;

/**
 * Compatibility holder for the moved lock type constants.
 */
@Deprecated
public final class DistributedReadWriteLock {

  private DistributedReadWriteLock() {}

  public static final class LockType {
    private LockType() {}

    public static final org.apache.accumulo.core.fate.zookeeper.lock.DistributedReadWriteLock.LockType READ =
        org.apache.accumulo.core.fate.zookeeper.lock.DistributedReadWriteLock.LockType.READ;
    public static final org.apache.accumulo.core.fate.zookeeper.lock.DistributedReadWriteLock.LockType WRITE =
        org.apache.accumulo.core.fate.zookeeper.lock.DistributedReadWriteLock.LockType.WRITE;
  }
}
